### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

using ll = long long;

// 计算以 x 为根的子树节点数
ll numChildren(int n, ll x) {
    int dep = 0;
    while (x > 1) {
        x /= 2;
        dep++;
    }
    return (1LL << (n - dep)) - 1;
}

// 计算节点 x 在先序遍历中的 DFS 序（从 0 开始）
ll calcDfn(int n, ll x) {
    ll ans = 0;
    while (x > 1) {
        ans++;
        if (x % 2 == 1) {
            ans += numChildren(n, x - 1);
        }
        x /= 2;
    }
    return ans;
}

// ODT 分裂操作：将包含 x 的区间分成 [L, x-1] 和 [x, R]
void split(map<ll, pair<ll, int>>& odt, ll x) {
    auto it = odt.upper_bound(x);
    if (it == odt.begin()) return;
    --it;
    ll L = it->first;
    ll R = it->second.first;
    int val = it->second.second;
    if (R < x || L == x) return; // 无需拆分
    odt.erase(it);
    odt[L] = { x - 1, val };
    odt[x] = { R, val };
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    map<ll, pair<ll, int>> odt;  // 左端点 -> {右端点, 值}，值 0 未通知，1 已通知
    ll ans = 0;
    odt[0] = { (1LL << n) - 1, 0 };

    for (int i = 0; i < q; i++) {
        ll a;
        cin >> a;
        ll right = a;
        while ((right * 2 + 1) < (1LL << n)) {
            right = right * 2 + 1;
        }
        ll L = calcDfn(n, a);
        ll R = calcDfn(n, right);

        split(odt, L);
        split(odt, R + 1);

        // 统计并删除 [L, R] 中未通知的区间
        auto it = odt.lower_bound(L);
        while (it != odt.end() && it->first <= R) {
            ll l = it->first;
            ll r = it->second.first;
            int val = it->second.second;
            if (val == 0) {
                ans += (r - l + 1);
            }
            it = odt.erase(it);
        }
        // 插入已通知区间
        odt[L] = { R, 1 };
        cout << ans << "\n";
    }

    return 0;
}
